interfaces.interface:
interface RecordingState {
  isRecording: boolean;
  mode: RecordingMode | null;  // 'screen' | 'webcam' | 'pip'
  selectedScreen: string | null;      // Source ID (string only)
  selectedWebcam: string | null;      // Device ID (string only)
  recordingDuration: number;
  outputFiles: string[];              // Completed recording paths
  startRecording: (mode: RecordingMode) => void;
  stopRecording: () => Promise<string[]>;
  setSelectedScreen: (id: string) => void;
  setSelectedWebcam: (id: string) => void;
  updateDuration: (seconds: number) => void;
}

interface Source {
  id: string;                    // Device/source ID
  name: string;                  // Display name
  type: 'screen' | 'window' | 'webcam';
  thumbnail?: string;            // Data URL for screens
}

Response: IPCResponse<{
  screens: Source[];    // All screen/window sources
  webcams: Source[];    // All webcam devices
}>
